from typing import Any, Optional, Union

from dataclasses_json import dataclass_json

from .seat import Seat

@dataclass_json
@dataclass
class Hold:
    id: int
    seat_id: int
    patron: Optional[Union[str, Seat]] = None
    state: str = "open"

@dataclass_json
@dataclass
class HoldBook:
    seats: dict[int, Hold] = field(default_factory=dict)

    def place_hold(self, seat_id: int, patron: Union[str, Seat]) -> None:
        """Place a hold on a seat."""
        if seat_id not in self.seats:
            raise LookupError(f"Seat {seat_id} not found.")
        if self.seats[seat_id].patron is not None:
            raise ValueError(f"Seat {seat_id} already has a patron.")
        if patron not in self.seats:
            raise LookupError(f"Patron {patron} not found.")
        self.seats[seat_id].patron = patron
        self.seats[seat_id].state = "placed"

    def claim_hold(self, seat_id: int) -> None:
        """Claim a hold on a seat."""
        if seat_id not in self.seats:
            raise LookupError(f"Seat {seat_id} not found.")
        if self.seats[seat_id].patron is not None:
            raise ValueError(f"Seat {seat_id} already has a patron.")
        self.seats[seat_id].state = "claimed"

    def cancel_hold(self, seat_id: int) -> None:
        """Cancel a hold on a seat."""
        if seat_id not in self.seats:
            raise LookupError(f"Seat {seat_id} not found.")
        if self.seats[seat_id].patron is None:
            raise ValueError(f"Seat {seat_id} does not have a patron.")
        self.seats[seat_id].state = "cancelled"

    def list_holds(self) -> list[Hold]:
        """List all holds."""
        return list(self.seats.values())

    def validate_patron(self, name: str) -> None:
        """Validate a patron's name."""
        if not isinstance(name, str):
            raise TypeError(f"Patron name must be a string, not {type(name)}.")
        if not name:
            raise ValueError(f"Patron name cannot be empty.")

